#!/usr/bin/env node
// Drives the real `bin/greet.js` CLI as a subprocess and asserts on its exit
// code and stdout. Exits 0 only when every feature in the map matches.
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");
const bin = resolve(root, "bin/greet.js");

const features = [
  { feature: "greet a name", args: ["ada"], code: 0, stdout: "hello, ada\n" },
  { feature: "default to world", args: [], code: 0, stdout: "hello, world\n" },
  { feature: "--help usage", args: ["--help"], code: 0, stdout: "usage: greet [name]\n" },
];

let failures = 0;
for (const f of features) {
  const r = spawnSync(process.execPath, [bin, ...f.args], { encoding: "utf8" });
  const ok = r.status === f.code && r.stdout === f.stdout && r.error === undefined;
  if (!ok) failures++;
  console.log(`${ok ? "PASS" : "FAIL"} ${f.feature}: exit=${r.status} stdout=${JSON.stringify(r.stdout)}`);
  if (!ok) console.log(`  expected exit=${f.code} stdout=${JSON.stringify(f.stdout)}${r.error ? ` error=${r.error.message}` : ""}`);
}

console.log(failures === 0 ? `verify-greet: ${features.length}/${features.length} features clean` : `verify-greet: ${failures} failing`);
process.exit(failures === 0 ? 0 : 1);

